# fmt: off
import uuid; from datetime import UTC, datetime; import pytest; from data_engine.config import settings; from data_engine.datahub.fetch_key import FetchKey; from data_engine.sources import gateway; from data_engine.sources import moomoo_ledger as ledger; from factors.shared import entity_resolution as er; from truealpha_runtime.testing import skip_or_fail; psycopg = pytest.importorskip("psycopg"); T1 = datetime(2026, 7, 1, tzinfo=UTC); T2 = datetime(2026, 7, 2, tzinfo=UTC); T3 = datetime(2026, 7, 3, tzinfo=UTC); NOW = datetime.now(UTC); REF = "raw.fetches:0"
@pytest.fixture
def conn():
    try: c = psycopg.connect(settings.database_url, connect_timeout=3)
    except psycopg.OperationalError: skip_or_fail("no reachable Postgres (make runtime-up && make db-migrate)")
    yield c; c.rollback(); c.close()
def _ident(conn, entity_id, value, *, transaction_time=T1, confidence=0.98, id_type="moomoo", source="openfigi"): return er.assert_identifier( conn, entity_id=entity_id, source=source, identifier_type=id_type, identifier_value=value, confidence=confidence, transaction_time=transaction_time, valid_from=transaction_time.date().isoformat(), raw_ref=REF, )
def test_identifier_roundtrip_idempotency_and_lookup(conn): uid = uuid.uuid4().hex[:10]; company = f"company:test:{uid}"; code = f"US.T{uid}"; er.ensure_entity(conn, company, "company", f"Test Co {uid}"); er.ensure_entity(conn, company, "company", "different name"); assert _ident(conn, company, code, transaction_time=T1); assert not _ident(conn, company, code, transaction_time=T2); assert _ident(conn, company, code, transaction_time=T2, confidence=0.9); assert er.resolve(conn, "moomoo", code, as_of=NOW) == company; assert er.resolve(conn, "moomoo", code, as_of=datetime(2026, 6, 1, tzinfo=UTC)) is None; assert er.resolve(conn, "moomoo", "US.DOES_NOT_EXIST", as_of=NOW) is None; assert er.crosswalk(conn, company, as_of=NOW) == {"moomoo": [code]}; assert (code, company) in er.identifiers(conn, "moomoo", as_of=NOW)
def test_identifier_correction_can_be_corrected_back(conn): uid = uuid.uuid4().hex[:10]; a, b = f"company:test:{uid}a", f"company:test:{uid}b"; isin = f"XX{uid}"; er.ensure_entity(conn, a, "company", "A"); er.ensure_entity(conn, b, "company", "B"); assert _ident(conn, a, isin, id_type="isin", transaction_time=T1); assert _ident(conn, b, isin, id_type="isin", transaction_time=T2); assert er.resolve(conn, "isin", isin, as_of=NOW) == b; assert _ident(conn, a, isin, id_type="isin", transaction_time=T3); assert er.resolve(conn, "isin", isin, as_of=NOW) == a; assert not _ident(conn, a, isin, id_type="isin", transaction_time=T3)
def test_resolve_follows_one_merge_hop(conn): uid = uuid.uuid4().hex[:10]; a, b = f"company:test:{uid}a", f"company:test:{uid}b"; er.ensure_entity(conn, a, "company", "A"); er.ensure_entity(conn, b, "company", "B"); _ident(conn, a, f"XX{uid}", id_type="isin"); er.add_edge( conn, from_id=a, to_id=b, relation_type="same_as", confidence=0.9, source="test", transaction_time=T2, valid_from="2026-07-02", raw_ref=REF, ); assert er.resolve(conn, "isin", f"XX{uid}", as_of=NOW) == b
def test_holds_edge_rerun_skips_and_new_filing_appends(conn):
    uid = uuid.uuid4().hex[:10]; etf, company = f"etf:test:{uid}", f"company:test:{uid}"; er.ensure_entity(conn, etf, "etf", "Test ETF"); er.ensure_entity(conn, company, "company", "Held Co")
    def hold(tx, valid): return er.add_edge( conn, from_id=etf, to_id=company, relation_type="holds", confidence=1.0, source="nport", transaction_time=tx, valid_from=valid, raw_ref=REF, )
    assert hold(T1, "2026-02-28"); assert not hold(T1, "2026-02-28"); assert not hold(T2, "2026-02-28"); assert er.add_edge( conn, from_id=etf, to_id=company, relation_type="holds", confidence=0.9, source="nport", transaction_time=T2, valid_from="2026-05-31", raw_ref=REF, )
def test_fund_holding_dual_lines_coexist_and_rerun_conflicts_away(conn):
    uid = uuid.uuid4().hex[:10]; etf, company = f"etf:test:{uid}", f"company:test:{uid}"; er.ensure_entity(conn, etf, "etf", "Test ETF"); er.ensure_entity(conn, company, "company", "Ping An Test")
    def line(isin, pct, value): return conn.execute( "\n            insert into staging.fund_holding_facts\n                (fund_id, holding_id, holding_name, report_period, transaction_time,\n                 isin, value_usd, percent_of_net_assets, confidence, raw_ref)\n            values (%s, %s, 'Ping An Test Co', '2026-02-28', %s, %s, %s, %s, 1.0, %s)\n            on conflict do nothing\n            returning id\n            ", (etf, company, T1, isin, value, pct, REF), ).fetchone()
    assert line("CNE000001R84", 2.08, 1000.0) is not None; assert line("CNE1000003X6", 1.10, 500.0) is not None; assert line("CNE000001R84", 2.08, 1000.0) is None; assert line("CNE1000003X6", 1.10, 500.0) is None
def test_the_moomoo_reads_count_the_rows_the_one_writer_wrote(conn, monkeypatch):
    from data_engine.sources import moomoo as mm; monkeypatch.setattr(gateway, "_pg_conn", conn); monkeypatch.setattr(gateway, "_writer", gateway.postgres_writer); monkeypatch.setattr(gateway.settings, "external_call_ledger", "postgres"); before = ledger.calls_this_month(); mm._call( object(), "request_history_kline", "test", lambda ctx: (mm.moomoo.RET_OK, []), request_uri="US.AAPL", identity=FetchKey("moomoo", "request_history_kline", "symbol:TEST", "2026-10-27"), )
    with pytest.raises(mm.MoomooConnectionError): mm._call( object(), "ep", "test", lambda ctx: (mm.moomoo.RET_ERROR, "boom"), identity=FetchKey("moomoo", "ep", "symbol:TEST", "2026-10-27"), )
    assert ledger.calls_this_month() == before + 2; monkeypatch.setattr(ledger, "distinct_stock_quota", lambda: len(ledger.kline_distinct_stocks_7d()))
    with pytest.raises(ledger.BudgetExceededError): ledger.gate("request_history_kline", "test", request_uri="moomoo://US.NEW_STOCK_OVER_QUOTA")
